 Since you tagged Powershell, I will give you ultra simple implementation of your requirements: 
 try {
    [xml]$xml = '<Person>
        <DOB>11181928</DOB>
        <LastName>Mouse</LastName>
        <FirstName>Mickey</FirstName>
        <City>Los Angeles</City>
        <State>CA</State>
    </Person>'

    if($xml.Person.FirstName -eq ""Mickey"" -and $xml.Person.LastName -eq ""Mouse"") {
        Write-Host ""Found Mickey Mouse!""
    } else {
        Write-Host ""Mickey Mouse Not Found!""
    }
}
catch {
    Write-Host ""Mickey Mouse Not Found!""
    Write-Host ""Error happened: $($_.Exception.Message)""
}""]"

