 If I don't use key_task, there are not duplicated symbols.","[""I found the solution. The problem was about that the code requested the keyboard values without a time delay. 
 key = stdscr.getch()

 So, the solution – is to make a time delay. But in order to not to block other code I have to create a new coroutine and send values (to a worker). 
 async def keyloop(stdscr, keyboard_queue):
    stdscr.nodelay(True)
    while True:
        key = stdscr.getch()
        if key >= 0:
            keyboard_queue.put_nowait(key)
        await asyncio.sleep(0.05)

async def worker(keyboard_queue, display_queue, stdscr):

    key = ''
    while True:
        try:
            keyboard_task = asyncio.create_task(keyboard_queue.get())
            done, pending = await asyncio.wait(
                [keyboard_task],
                return_when=asyncio.FIRST_COMPLETED
            )
            for task in done:
                key_0 = keyboard_task.result()
                if key_0 >= 0:
                    key = key_0

            for task in pending:
                task.cancel()
                try:
                    await task
                except asyncio.CancelledError:
                    pass
        except Exception as e:
            pass""]"

